def require_api_key_scope(required_scope: str):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            key = get_api_key()
            if key is None:
                return jsonify({"error": "valid API key required"}), 401
            g.api_key = key
            return fn(*args, **kwargs)
        return wrapper
    return decorator

